import { useMemo } from "react";
import { useNavigate } from "react-router-dom";
import AddToCartButton from "../components/AddToCartButton";
import { useWishlist } from "../context/WishlistContext";

export default function ProductCard({ p, showRemove = false }) {
    const navigate = useNavigate();
    const { toggleWishlist, isWishlisted } = useWishlist();

    const data = useMemo(() => {
        const id = p.id || p.Id;
        const name = p.name || p.Name;
        const brand = p.brand || p.Brand;
        const imageUrl = p.imageUrl || p.ImageUrl;

        const price =
            p.price ?? p.Price ?? p.minPrice ?? p.MinPrice ?? 0;

        const discount = p.discount ?? p.DiscountPercentage ?? 0;
        const isHotDeal = p.isHotDeal ?? p.IsHotDeal ?? false;
        const dealEnd = p.dealEndDate ?? p.DealEndDate;

        const isDealActive =
            isHotDeal &&
            discount > 0 &&
            dealEnd &&
            new Date(dealEnd) > new Date();

        const finalPrice = isDealActive
            ? price - (price * discount) / 100
            : price;

        const variant =
            p.defaultVariant ||
            (p.variants?.length ? p.variants[0] : null);

        return {
            id,
            name,
            brand,
            imageUrl,
            price,
            finalPrice,
            discount,
            isDealActive,
            variant
        };
    }, [p]);

    const wishlisted = isWishlisted(data.id);

    return (
        <div className="group bg-white rounded-2xl border border-gray-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 flex flex-col overflow-hidden">

            {/* 🔥 IMAGE SECTION */}
            <div
                onClick={() => navigate(`/product/${data.id}`)}
                className="relative h-48 bg-gray-50 flex items-center justify-center p-4 cursor-pointer overflow-hidden"
            >
                {/* 🔴 DISCOUNT + HURRY */}
                {data.isDealActive && (
                    <div className="absolute top-2 left-2 flex flex-col gap-1 z-10">
                        <span className="bg-red-500 text-white text-[11px] font-bold px-2 py-[2px] rounded shadow">
                            {data.discount}% OFF
                        </span>
                        <span className="bg-black text-white text-[10px] px-2 py-[2px] rounded opacity-90">
                            🔥 Hurry!
                        </span>
                    </div>
                )}

                {/* IMAGE */}
                <img
                    src={data.imageUrl || "/images/no-image.png"}
                    alt={data.name}
                    className="w-full h-full object-contain group-hover:scale-105 transition duration-300"
                />

                {/* ❤️ WISHLIST */}
                {!showRemove && (
                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            toggleWishlist(p);
                        }}
                        className={`absolute top-2 right-2 p-2 rounded-full shadow transition 
                        ${wishlisted ? "bg-pink-500 text-white" : "bg-white text-gray-600 hover:bg-gray-100"}`}
                    >
                        {wishlisted ? "❤️" : "🤍"}
                    </button>
                )}
            </div>

            {/* 📦 CONTENT */}
            <div className="p-4 flex flex-col flex-grow">

                {/* BRAND */}
                <p className="text-xs text-gray-400 uppercase tracking-wide">
                    {data.brand}
                </p>

                {/* NAME */}
                <h3
                    onClick={() => navigate(`/product/${data.id}`)}
                    className="text-sm font-semibold text-gray-900 mt-1 line-clamp-2 cursor-pointer hover:text-pink-600 transition"
                >
                    {data.name}
                </h3>

                {/* 💰 PRICE */}
                <div className="mt-2">

                    <div className="flex items-center gap-2 flex-wrap">

                        {/* FINAL PRICE */}
                        <span className="text-lg font-bold text-gray-900">
                            ₹{Math.round(data.finalPrice).toLocaleString("en-IN")}
                        </span>

                        {/* ORIGINAL */}
                        {data.isDealActive && (
                            <span className="text-sm text-gray-400 line-through">
                                ₹{Math.round(data.price).toLocaleString("en-IN")}
                            </span>
                        )}

                        {/* % OFF */}
                        {data.isDealActive && (
                            <span className="text-sm text-green-600 font-semibold">
                                {data.discount}% off
                            </span>
                        )}
                    </div>

                    {/* SAVINGS */}
                    {data.isDealActive && (
                        <p className="text-xs text-green-600 font-medium mt-1">
                            You save ₹{Math.round(data.price - data.finalPrice)}
                        </p>
                    )}
                </div>

                {/* 🚚 DELIVERY */}
                <p className="text-xs text-gray-500 mt-2">
                    🚚 Delivery in 3–5 days
                </p>

                {/* 🛒 ACTION */}
                <div className="mt-auto pt-3">

                    {data.variant ? (
                        <AddToCartButton
                            productId={data.id}
                            variantId={data.variant.id}
                            minQty={data.variant.minQty || 1}
                        />
                    ) : (
                        <p className="text-xs text-red-500">
                            Variant unavailable
                        </p>
                    )}

                </div>

            </div>
        </div>
    );
}