import { useCart } from "../context/CartContext";
import { useState } from "react";

export default function AddToCartButton({
    productId,
    variantId,
    minQty = 1
}) {

    const { addToCart, updateCart, removeFromCart, getQty } = useCart();

    const qty = getQty(variantId);

    const [loading, setLoading] = useState(false);

    // ➕ ADD
    const handleAdd = async () => {
        try {
            setLoading(true);
            await addToCart(productId, variantId, minQty);
        } finally {
            setLoading(false);
        }
    };

    // ➕ INCREASE
    const increase = () => {
        updateCart(variantId, qty + 1);
    };

    // ➖ DECREASE
    const decrease = () => {
        if (qty <= 1) {
            removeFromCart(variantId);
        } else {
            updateCart(variantId, qty - 1);
        }
    };

    return (
        <div className="w-full">

            {qty === 0 ? (
                <button
                    onClick={handleAdd}
                    disabled={loading}
                    className="w-full border-2 border-pink-500 text-pink-600 font-semibold py-2 rounded-lg hover:bg-pink-500 hover:text-white transition disabled:opacity-50"
                >
                    {loading ? "Adding..." : "Add to Cart"}
                </button>
            ) : (
                <div className="flex items-center justify-between border-2 border-pink-500 rounded-lg overflow-hidden">

                    <button
                        onClick={decrease}
                        className="px-4 py-2 hover:bg-gray-100"
                    >
                        −
                    </button>

                    <span className="font-semibold text-lg">
                        {qty}
                    </span>

                    <button
                        onClick={increase}
                        className="px-4 py-2 hover:bg-gray-100"
                    >
                        +
                    </button>

                </div>
            )}

        </div>
    );
}