import { useState } from "react";

export default function CartSummary({ summary, coupon, setCoupon, applyCoupon }) {

    const [msg, setMsg] = useState("");

    const subtotal = summary?.subtotal || 0;
    const percent = Math.min((subtotal / 500) * 100, 100);

    const handleApply = async () => {
        await applyCoupon();
        setMsg("🎉 Coupon Applied!");
        setTimeout(() => setMsg(""), 2000);
    };

    return (
        <div className="bg-white p-6 rounded-2xl shadow sticky top-20">

            <h2 className="font-bold text-lg mb-4">Price Details</h2>

            {/* DELIVERY BAR */}
            <div className="bg-green-50 p-3 rounded-xl mb-4">

                <p className="text-sm">
                    {subtotal >= 500
                        ? "🎉 Free Delivery!"
                        : `₹${500 - subtotal} away from free delivery`}
                </p>

                <div className="bg-gray-200 h-2 rounded mt-2">
                    <div
                        className="bg-green-500 h-2 rounded transition-all duration-700"
                        style={{ width: `${percent}%` }}
                    />
                </div>
            </div>

            {/* COUPON */}
            <div className="flex gap-2 mb-3">
                <input
                    value={coupon}
                    onChange={(e) => setCoupon(e.target.value)}
                    placeholder="Enter Coupon"
                    className="border px-3 py-2 flex-grow rounded-lg"
                />

                <button
                    onClick={handleApply}
                    className="bg-pink-500 text-white px-4 rounded-lg"
                >
                    Apply
                </button>
            </div>

            {msg && (
                <div className="text-green-600 animate-bounce text-sm mb-2">
                    {msg}
                </div>
            )}

            {/* SUMMARY */}
            <div className="space-y-2 text-sm">

                <div className="flex justify-between">
                    <span>Subtotal</span>
                    <span>₹{summary?.subtotal}</span>
                </div>

                <div className="flex justify-between">
                    <span>GST</span>
                    <span>₹{summary?.gst}</span>
                </div>

                <div className="flex justify-between text-green-600">
                    <span>You Saved</span>
                    <span>-₹{summary?.saved}</span>
                </div>

                <div className="flex justify-between">
                    <span>Delivery</span>
                    <span>{summary?.delivery === 0 ? "FREE" : "₹80"}</span>
                </div>

                <div className="flex justify-between text-red-500">
                    <span>Coupon</span>
                    <span>-₹{summary?.couponDiscount}</span>
                </div>

                <hr />

                <div className="flex justify-between font-bold text-lg">
                    <span>Total</span>
                    <span>₹{summary?.total}</span>
                </div>

            </div>

        </div>
    );
}