import { useParams } from "react-router-dom";
import { useEffect, useState } from "react";
import API from "../services/api";
import AddToCartButton from "../components/AddToCartButton";

export default function ProductDetails() {
    const { id } = useParams();

    const [product, setProduct] = useState(null);
    const [selectedVariant, setSelectedVariant] = useState(null);
    const [showSpecs, setShowSpecs] = useState(false);

    // 🔥 LOAD PRODUCT
    useEffect(() => {
        API.get(`/api/products/${id}`)
            .then(res => {
                setProduct(res.data);
                if (res.data.variants?.length > 0) {
                    setSelectedVariant(res.data.variants[0]);
                }
            })
            .catch(console.error);
    }, [id]);

    if (!product) {
        return <div className="p-6">Loading product...</div>;
    }

    return (
            <div className="max-w-7xl mx-auto px-6 py-8 grid md:grid-cols-2 gap-12">

                {/* 🖼 IMAGE */}
                <div className="bg-white rounded-3xl shadow-xl p-6 hover:shadow-2xl transition">
                    <img
                        src={product.imageUrl || "/images/no-image.png"}
                        className="w-full h-[420px] object-contain"
                    />
                </div>

                {/* 📦 DETAILS */}
                <div className="flex flex-col">

                    {/* BRAND */}
                    <p className="text-gray-400 uppercase tracking-widest text-xs">
                        {product.brand}
                    </p>

                    {/* NAME */}
                    <h1 className="text-3xl font-bold mt-1">
                        {product.name}
                    </h1>

                    {/* DESCRIPTION */}
                    <p className="text-gray-600 mt-4 text-sm leading-relaxed">
                        {product.description || "No description available"}
                    </p>

                    {/* PRICE */}
                    <div className="mt-5">
                        <span className="text-3xl font-bold text-pink-600">
                            ₹{selectedVariant?.price}
                        </span>
                    </div>

                    {/* VARIANTS */}
                    <div className="mt-8">
                        <h3 className="font-semibold mb-3 text-lg">Select Model</h3>

                        <div className="grid grid-cols-2 gap-3">
                            {product.variants?.map((v, i) => (
                                <button
                                    key={v.id}
                                    onClick={() => setSelectedVariant(v)}
                                    className={`p-3 rounded-xl border text-left transition-all
                    ${selectedVariant?.id === v.id
                                            ? "border-pink-500 bg-pink-50 shadow-md"
                                            : "hover:border-gray-400"
                                        }`}
                                >
                                    <p className="font-medium">
                                        {v.model || `Model ${i + 1}`}
                                    </p>
                                    <p className="text-xs text-gray-500">
                                        {v.size} {v.unit} {v.packSize && `(${v.packSize})`}
                                    </p>
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* 🛒 REUSABLE ADD TO CART */}
                    <div className="mt-8">
                        {selectedVariant && (
                            <AddToCartButton
                                productId={product.id}
                                variantId={selectedVariant.id}
                                minQty={selectedVariant.minQty}
                                maxQty={selectedVariant.maxQty}
                                stepQty={selectedVariant.stepQty}
                            />
                        )}
                    </div>

                    {/* SPECIFICATIONS */}
                    <div className="mt-10">
                        <button
                            onClick={() => setShowSpecs(!showSpecs)}
                            className="text-blue-600 font-semibold hover:underline"
                        >
                            {showSpecs ? "Hide Specifications" : "View Specifications"}
                        </button>

                        {showSpecs && (
                            <div className="mt-4 bg-white border rounded-xl overflow-hidden shadow-sm">
                                {product.specifications?.length > 0 ? (
                                    product.specifications.map((s, i) => (
                                        <div
                                            key={i}
                                            className="flex justify-between px-4 py-3 border-b text-sm"
                                        >
                                            <span className="text-gray-500">{s.key}</span>
                                            <span className="font-medium">{s.value}</span>
                                        </div>
                                    ))
                                ) : (
                                    <p className="p-4 text-gray-500">
                                        No specifications available
                                    </p>
                                )}
                            </div>
                        )}
                    </div>

                </div>
            </div>
    );
}