import { createContext, useContext, useState, useEffect } from "react";
import API from "../services/api";

const WishlistContext = createContext();
export const useWishlist = () => useContext(WishlistContext);

export const WishlistProvider = ({ children }) => {

    const [wishlist, setWishlist] = useState([]);
    const [wishlistCount, setWishlistCount] = useState(0);

    useEffect(() => {
        loadWishlist();
    }, []);

    const loadWishlist = async () => {
        try {
            const res = await API.get("/api/wishlist");
            setWishlist(res.data);

            const countRes = await API.get("/api/wishlist/count");
            setWishlistCount(countRes.data);
        } catch (err) {
            console.error("Wishlist load failed", err);
        }
    };

    // 🔥 FAST TOGGLE
    const toggleWishlist = async (product) => {
        const exists = wishlist.some(x => x.id === product.id);

        // ⚡ INSTANT UI
        let updated;
        if (exists) {
            updated = wishlist.filter(x => x.id !== product.id);
        } else {
            updated = [...wishlist, product];
        }

        setWishlist(updated);
        setWishlistCount(updated.length);

        // 🔄 BACKEND
        try {
            await API.post("/api/wishlist/toggle", product.id);
        } catch (err) {
            console.error("Toggle failed", err);
        }
    };

    const isWishlisted = (id) => {
        return wishlist.some(x => x.id === id);
    };

    return (
        <WishlistContext.Provider
            value={{
                wishlist,
                wishlistCount,
                toggleWishlist,
                isWishlisted,
                loadWishlist
            }}
        >
            {children}
        </WishlistContext.Provider>
    );
};